const adminRoute=location.pathname.replace(/\/$/,'')==='/admin';
const $=q=>document.querySelector(q),pages={home:['⌂','메인'],entry:['＋','할일 추가'],planner:['▦','주간 계획'],tutor:['✧','공부 도우미'],social:['☏','소통'],settings:['⚙','설정'],admin:['⚿','관리자']};
const s={data:null,userId:null,community:{member:null,person:null,people:[],notices:[],rooms:[],applications:[]},classTables:{},homeWeek:sunday(today()),entryWeek:sunday(today()),planWeek:sunday(today()),homeMonth:today(),entryMonth:today(),entries:[],entryIndex:0,entryText:'',editId:null,forms:{},room:null,messages:[],tutor:{enabled:false,subject:'수학',mode:'concept',question:'',image:null,result:null,revealed:1},meals:'급식 연결을 확인하고 있어요.'};
