const logo='<span class="restored-logo"><svg viewBox="0 0 32 32" width="32" height="32" aria-hidden="true"><rect x="5" y="7" width="22" height="21" rx="5" fill="none" stroke="currentColor" stroke-width="2.2"/><path d="M10 4v6m12-6v6M5 14h22M10 23v-5l6 5 6-5v5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
