const schoolURL=(p,week)=>'/api/school?school='+encodeURIComponent(p.school)+'&grade='+encodeURIComponent(p.grade)+'&className='+encodeURIComponent(p.className)+'&week='+week;
async function getSchool(p=s.data.profile,week=s.homeWeek){if(!p.school?.trim())return null;return api(schoolURL(p,week));}
async function checkSchool(){const f=$('#profile-form');if(!f)return;const v=fd(f),ticket=++schoolRequest;try{const r=await getSchool({school:v.school?.trim(),grade:v.grade?.trim(),className:v.className?.trim()});if(ticket!==schoolRequest||!f.isConnected)return;s.school=r;s.schoolKey=[v.school,v.grade,v.className].map(x=>x?.trim()||'').join('|');const box=f.querySelector('#school-state');if(box)box.textContent=r?.schedule?'등록된 학교 일과를 불러왔어요. '+(r.table?'같은 반 시간표도 함께 적용됩니다.':'과목만 입력해 주세요.'):'이 학교의 첫 등록이에요. 사진을 읽고 시각을 확인하거나 직접 작성하세요.';if(r?.schedule){const config={...r.schedule,table:r.table?.table||s.data.profile.timetable.map(d=>Array.from({length:9},(_,i)=>d[i]||''))};fillSchedule(f,config);const timing=f.querySelector('.schedule-editor details');if(timing)timing.hidden=true;f.querySelectorAll('[data-action=analyze-schedule],[data-action=science-preset],#schedule-photo').forEach(el=>el.disabled=true);f.querySelectorAll('[name^=slot-]').forEach(el=>el.readOnly=!!r.table);}else{f.querySelectorAll('[name^=slot-]').forEach(el=>el.readOnly=false);f.querySelectorAll('[data-action=analyze-schedule],[data-action=science-preset],#schedule-photo').forEach(el=>el.disabled=false);const details=f.querySelector('.schedule-editor details');if(details)details.hidden=false;}capture();}catch(err){error(err);}}
async function sharedSetup(){try{const p=s.data.profile,r=await getSchool(p);s.school=r;if(!r?.schedule){await api('/api/school',{method:'POST',body:JSON.stringify({action:'schedule',daySchedule:p.daySchedule||defaultSchedule(p.periodTimes),periodTimes:p.periodTimes||PERIODS})});}if(!r?.table)await api('/api/school',{method:'POST',body:JSON.stringify({action:'table',week:s.homeWeek,table:p.timetable.map(d=>Array.from({length:9},(_,i)=>d[i]||''))})});s.classTables={};}catch(err){if(err.status!==409)throw err;s.school=await getSchool();s.classTables={};toast('먼저 등록된 학교·학급 시간표를 적용했어요.');}}

let booting=true,view='home',drag=null,minute='',noticeTimer,saveTimer;
const openedDetails=new Set();
document.addEventListener('toggle',event=>{const d=event.target;if(d.tagName!=='DETAILS'||!d.isConnected)return;const key=view+':'+d.querySelector('summary')?.textContent;d.open?openedDetails.add(key):openedDetails.delete(key);},true);
const toast=text=>feedback(text,'info');
const error=err=>feedback(err.message||'요청을 처리하지 못했습니다. 다시 시도해 주세요.','error');
cloud.onFeedback=feedback;
const inflight=new Set();
const fd=f=>Object.fromEntries(new FormData(f));
function persist(){if(!cloud.user)return;try{sessionStorage.setItem('campus-draft-'+cloud.user.id,JSON.stringify({forms:s.forms,entries:s.entries,entryIndex:s.entryIndex,entryText:s.entryText,editId:s.editId}));}catch{toast('초안 임시 저장이 어려워요. 입력 내용을 복사해 주세요.');}}
function capture(){if(!cloud.user)return;for(const f of document.querySelectorAll('form')){if(['tutor-form','entry-form'].includes(f.id))continue;if(f.querySelector('[type=password]'))continue;const pending=s.forms[f.id];s.forms[f.id]=fd(f);if(pending?.clientId)Object.assign(s.forms[f.id],{clientId:pending.clientId,fingerprint:pending.fingerprint});for(const c of f.querySelectorAll('[type=checkbox]'))s.forms[f.id][c.name]=c.checked;}captureEntry();persist();}
function restore(){for(const[id,values]of Object.entries(s.forms)){const f=document.getElementById(id);if(!f)continue;if(f.querySelector('.schedule-rows')){const rows=[];for(let i=0;i<30&&Object.hasOwn(values,'schedule-label-'+i);i++)rows.push({label:values['schedule-label-'+i],start:values['schedule-start-'+i],end:values['schedule-end-'+i],period:values['schedule-period-'+i],days:String(values['schedule-days-'+i]||'').split(','),examOnly:!!values['schedule-exam-'+i]});if(rows.length)f.querySelector('.schedule-rows').innerHTML=scheduleRows(rows);}for(const[k,v]of Object.entries(values)){const el=f.elements.namedItem(k);if(!el||!el.tagName||el.type==='file')continue;if(el.type==='checkbox')el.checked=!!v;else el.value=v;}}}
function captureEntry(){const f=$('#entry-form'),d=s.entries[s.entryIndex];if(!f||!d||!f.elements.title)return;const v=fd(f);Object.assign(d,{title:v.title,taskType:v.taskType,category:['study','bring','buy','other'].includes(v.taskType)?v.taskType:'assignment',totalMinutes:Number(v.minutes),durationRequired:!v.minutes,minutesEstimated:!v.minutes,priority:Number(v.priority),difficulty:Number(v.difficulty),note:v.note||'',completedMinutes:Number(v.completedMinutes||0),startDate:v.startDate||null});Object.assign(d.fields,{subject:v.subject||null,due:v.due||null,time:v.time||null});}
function capacity(){const now=Date.now(),spent=s.data.tasks.reduce((sum,t)=>sum+(t.studyLog||[]).filter(l=>iso(new Date(l.at))===today()).reduce((n,l)=>n+l.minutes,0),0);return {condition:s.data.profile.conditions?.[today()]||'middle',weekly:s.data.profile.weeklyMinutes,overrides:s.data.profile.dateOverrides||{},today:today(),now,spent};}
function save(){if(!cloud.user)throw new Error('로그인이 필요해요.');if(cloud.locked)throw new Error('저장이 잠겼어요. 백업 후 새로고침해 주세요.');if(!validateBackup(s.data))throw new Error('날짜·시간·입력 범위를 확인해 주세요.');s.data.acceptedPlan=null;queueSave(s.data);}
async function saved(){const end=Date.now()+20000;while(cloud.running||cloud.pending){if(cloud.locked||/실패|충돌|만료/.test(cloud.status)||Date.now()>end)throw new Error('저장에 실패했습니다. 입력 내용은 이 탭에 남아 있습니다. 저장 상태와 연결을 확인한 뒤 다시 시도해 주세요.');await new Promise(r=>setTimeout(r,200));}}
async function campus(action,body={}){return api('/api/campus',{method:'POST',body:JSON.stringify({action,...body})});}
async function refreshCommunity(){const id=cloud.user?.id;if(!id)return;try{const c=await api('/api/campus');if(cloud.user?.id===id){s.community=c;if(s.room&&!c.rooms.some(r=>r.id===s.room.id)){s.room=null;s.messages=[];delete s.forms['message-form'];}}}catch(err){toast('학급 연결: '+err.message);}}
async function loadTable(week){if(!cloud.user||Object.hasOwn(s.classTables,week))return;const id=cloud.user.id;s.classTables[week]=null;try{const shared=await getSchool(s.data.profile,week),verified=s.community.member?(await api('/api/campus?week='+week)).table:null;if(cloud.user?.id!==id)return;s.school=shared;s.classTables[week]={...(verified||{}),...(shared?.table||{}),...(shared?.schedule||{})};if(!s.classTables[week].table)delete s.classTables[week].table;if(['home','entry'].includes(view)){capture();render();}}catch(err){delete s.classTables[week];error(err);}}
function go(next){if(!pages[next])next='home';if(!visiblePages().some(([v])=>v===next))next='home';view=next;if(location.hash!=='#'+next)location.hash=next;render();window.scrollTo(0,0);}
function authScreen(){if(adminRoute)return '<main class="login-shell"><h1>메타시간표 관리자 로그인</h1><p>기존 관리자 계정으로 로그인하세요. 추가 인증은 없습니다.</p><form id="login-form"><label>이메일<input name="email" type="email" autocomplete="username" required></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" required></label><button class="button primary">로그인</button></form><a href="/">일반 사용자 페이지</a></main>';return `<main class="login-shell"><a class="login-brand" href="#home">${logo} 메타시간표</a><h1>시간을 아끼다, 메타시간표</h1><p>로그인하면 나만의 계획과 학교 소식을 한곳에서 볼 수 있어요.</p>${authPage(null).replace(/<button class="text-button" data-action="demo">.*?<\/button>/,'').replace('학교 정보는 선택 입력입니다.','처음 로그인하면 학교·학년·반과 일일 시간을 입력합니다.').replace('로그인 전 사용하던 기록은 자동 업로드하지 않습니다. 로그인 후 직접 가져올 수 있어요.','이전 버전의 로그인 전 기록은 설정에서 직접 가져올 수 있어요.')}</main>`;}
function settings(){const p=s.data.profile,c=s.community;return `<section class="panel"><h1>${p.campusOnboarded?'나의 설정':'처음 한 번, 나에게 맞게'}</h1><p>한 줄 입력 → 옵션 확인 → 추가하기. 선생님이 없어도 개인 모드로 쓸 수 있어요.</p><form id="profile-form"><div class="form-grid">${[['name','표시 이름'],['school','학교 이름 (정확히)'],['grade','학년'],['className','반']].map(([k,l])=>`<label>${l}<input name="${k}" maxlength="100" required value="${e(p[k])}"></label>`).join('')}</div><p class="muted">같은 학교는 일과 시각, 같은 반은 과목 시간표를 공유해요. 학급은 선생님 개설 후 같은 소속만 코드 없이 입장해요. 그룹은 승인 후 직접 입장해요.</p><h2>요일별 일일 시간</h2><div class="week-inputs">${[0,1,2,3,4,5,6].map(d=>`<label>${'일월화수목금토'[d]}<input name="capacity-${d}" type="number" min="0" max="720" required value="${p.weeklyMinutes[d]}"><small>분</small></label>`).join('')}</div><label class="checkbox-label"><input name="discoverable" type="checkbox" ${c.person?.discoverable?'checked':''}>같은 학교 사용자에게 표시 이름·학년·반을 공개하고 개인 채팅을 받겠습니다. 자동으로 그룹에 가입하지 않습니다.</label><p>현재 역할: ${ROLE_NAMES[role()]} · 역할은 관리자가 지정합니다.</p>${!p.campusOnboarded?'<p id="school-state" role="status">학교 이름을 입력하면 공통 일과를 확인해요.</p>'+scheduleEditor(p,s.homeWeek):(!c.member||['teacher','admin'].includes(role())?btn('시간표·야자 일과 편집','edit-table'):'<p>학급 시간표는 선생님이 관리합니다.</p>')}<button class="button primary">설정 저장하고 시작하기</button></form><p>${e(cloud.user.email)} · ${cloud.user.role==='admin'?'관리자':'회원'} ${c.person?.teacher_status==='approved'?'· 승인된 선생님':''}</p>${btn('로그아웃','logout')}${btn('내 자료 백업','backup')}${btn('이전 로그인 전 기록 가져오기','import-local')}</section>${appearancePanel(p)}${remindersPanel(p,{focus:false})}<section class="panel"><h2>학교·학급 연결</h2><p>소통 페이지에서 학급과 그룹에 직접 입장하거나 탈퇴할 수 있어요. 역할 변경은 관리자에게 문의하세요.</p><p>관리자는 개인 채팅·학급·그룹 대화를 열람할 수 있습니다.</p></section>`;}
function render(){
 if(booting){$('#app').innerHTML='<main class="login-shell"><h1>내 계정을 확인하고 있어요…</h1></main>';return;}
 if(!cloud.user){applyAppearance(null);$('#app').innerHTML=authScreen();return;}
 if(adminRoute){view='admin';applyAppearance(s.data.profile.appearance);$('#app').innerHTML='<main class="admin-shell"><header class="campus-header"><span>메타시간표 · 관리자 전용</span>'+btn('로그아웃','logout')+'</header>'+(cloud.user.role==='admin'?adminPage(s.admin,s.adminError):'<section class="panel"><h1>접근 권한이 없습니다.</h1><p>관리자 계정만 사용할 수 있습니다.</p><a href="/">메타시간표로 돌아가기</a></section>')+'</main>';if(cloud.user.role==='admin'&&!s.admin&&!s.adminLoading&&!s.adminError)loadAdmin();return;}
 if(!s.data.profile.campusOnboarded)view='settings';
 if(!visiblePages().some(([v])=>v===view))view='home';
 applyAppearance(s.data.profile.appearance);const cap=capacity(),p=plan(s.data.tasks,cap,today());
 $('#app').innerHTML=`<aside class="campus-sidebar"><a class="brand" href="#home">${logo} 메타시간표</a><p class="muted">시간을 아끼다, 메타시간표</p><nav aria-label="주 메뉴">${visiblePages().map(([v,[icon,name]])=>`<a href="#${v}" class="campus-nav ${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span>${icon}</span>${name}${v==='social'?' <small id="unread-count"></small>':''}</a>`).join('')}</nav><button class="profile-shortcut" data-action="profile"><span class="avatar">${e(s.data.profile.name.slice(0,1)||'나')}</span><span><b>${e(s.data.profile.name)}</b><small>프로필 · 개인 설정</small></span></button></aside><main id="main" class="campus-main" tabindex="-1"><header class="campus-header"><span id="current-clock">${new Date().toLocaleString('ko-KR')}</span><span id="save-status" role="status">${e(cloud.status)}</span></header>${cloud.locked?'<p class="warning-text">저장이 잠겼어요. 설정의 백업으로 임시 기록을 보관한 뒤 새로고침해 주세요.</p>':''}${s.community.site?.announcement?'<section class="panel site-announcement">'+e(s.community.site.announcement)+'</section>':''}${view==='admin'?adminPage(s.admin,s.adminError):view==='home'?homePage(s,p,dailyCapacity(cap,today())):view==='entry'?entryPage(s):view==='planner'?plannerPage(s,weekPlan(s.data.tasks,cap,today(),s.planWeek)):view==='tutor'?tutorPage(s):view==='social'?socialPage(s):settings()}</main>`;
 if(view==='admin'&&!s.admin&&!s.adminLoading&&!s.adminError)loadAdmin();
 updateUnread();restore();const setup=$('#profile-form');if(setup?.querySelector('.schedule-editor')&&s.schoolKey===['school','grade','className'].map(k=>setup.elements[k].value.trim()).join('|')){const timing=setup.querySelector('.schedule-editor details');if(timing)timing.hidden=!!s.school?.schedule;setup.querySelectorAll('[name^=slot-]').forEach(el=>el.readOnly=!!s.school?.table);setup.querySelectorAll('[data-action=analyze-schedule],[data-action=science-preset],#schedule-photo').forEach(el=>el.disabled=!!s.school?.schedule);}for(const d of document.querySelectorAll('details'))d.open=openedDetails.has(view+':'+d.querySelector('summary')?.textContent);if(view==='home'){loadTable(s.homeWeek);loadTable(sunday(today()));}if(view==='entry')loadTable(s.entryWeek);
}
async function loadAdmin(page=0,q='',section=s.admin?.section||'users'){if(cloud.user?.role!=='admin')return;s.adminLoading=true;s.adminError=false;try{s.admin={...await api('/api/admin?section='+section+'&page='+page+'&q='+encodeURIComponent(q)),q};}catch(err){s.adminError=true;error(err);}finally{s.adminLoading=false;if(view==='admin')render();}}
async function openSchedule(id){const r=await api('/api/schedule?id='+encodeURIComponent(id));if(r.status!=='complete')throw new Error('완료된 분석 결과가 아니에요.');if(!$('#table-form'))$('#campus-dialog')?.close();if(!$('#table-form')&&!$('#profile-form .schedule-editor')){$('#campus-dialog')?.close();await editTable();}const f=$('#table-form')||$('#profile-form');fillSchedule(f,r.result);const box=f.querySelector('#schedule-photo-preview');box.innerHTML='<p>사진 분석 초안이에요. 아래 과목·시각을 확인한 뒤 저장하세요.</p>'+r.result.uncertainties.map(x=>'<p class="warning-text">'+e(x)+'</p>').join('')+'<a href="#settings/'+e(id)+'">이 분석 결과 다시 열기</a>';capture();}
function modal(title,body){$('#campus-dialog')?.remove();const d=document.createElement('dialog');d.id='campus-dialog';d.innerHTML=`<div class="panel-heading"><h2>${e(title)}</h2>${btn('닫기','close-dialog')}</div>${body}`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());}
function editTask(id){const t=s.data.tasks.find(t=>t.id===id);if(!t)return;s.entries=[{...structuredClone(t),taskType:typeOf(t),totalMinutes:t.totalMinutes??t.minutes,warnings:[]}];s.entryIndex=0;s.entryText=t.source||t.title;s.editId=id;go('entry');}
function pasteNotice(text,base=today()){capture();const rows=inspectNotice(text,s.data.tasks,base,subjectList());s.entries=rows.map(r=>({...r.parsed,taskType:r.old?typeOf(r.old):typeOf(r.parsed),priority:r.parsed.priority!==2?r.parsed.priority:r.old?.priority||2,difficulty:r.parsed.difficulty||r.old?.difficulty||2,durationRequired:!r.old,note:r.old?.note||'',completedMinutes:r.old?.completedMinutes||0,totalMinutes:r.parsed.minutesEstimated?(r.old?.totalMinutes??r.parsed.totalMinutes):r.parsed.totalMinutes,fields:{...r.parsed.fields,...r.old?.fields,...Object.fromEntries(Object.entries(r.parsed.fields).filter(([,v])=>v!==null))},noticeRow:r,targetId:r.targetId,warnings:r.warnings}));s.entryIndex=0;s.editId=null;s.entryText=text;$('#campus-dialog')?.close();go('entry');}
