function planDay(date){const cap=capacity(),p=weekPlan(s.data.tasks,cap,today(),sunday(date)),d=p.days.find(d=>d.date===date);modal(dayLabel(date)+' 자세한 계획',`${d.items.map(i=>`<article class="compact-task"><strong>${e(s.data.tasks.find(t=>t.id===i.id)?.fields.subject||'')} · ${e(i.title)} · ${i.minutes}분</strong>${btn('할일 수정','edit',`data-id="${e(i.id)}"`)}</article>`).join('')||'<p>배치된 할일이 없어요.</p>'}<h3>이 날짜에 직접 배치</h3><form id="pin-form"><input type="hidden" name="date" value="${date}"><label>할일<select name="taskId">${s.data.tasks.filter(t=>!t.done&&['study','assignment'].includes(t.category)).map(t=>`<option value="${e(t.id)}">${e(t.title)}</option>`).join('')}</select></label><label>배치할 시간 (0이면 이 날짜 직접 배치 해제)<input type="number" name="minutes" min="0" max="720" required value="30"></label><button class="button primary">배치 저장</button></form><h3>이날 일일 시간 조정</h3><form id="capacity-form"><input type="hidden" name="date" value="${date}"><label>총 일일 시간 (분)<input name="minutes" type="number" min="0" max="720" required value="${s.data.profile.dateOverrides?.[date]??s.data.profile.weeklyMinutes[new Date(date+'T12:00:00').getDay()]}"></label><button class="button secondary">시간 변경</button></form><details><summary>직접 배치 전체 확인</summary>${s.data.tasks.flatMap(t=>(t.planSlots||[]).map(slot=>`<p>${e(t.title)} · ${slot.date} · ${slot.minutes}분 ${btn('해제','unpin',`data-id="${e(t.id)}" data-date="${slot.date}"`)}</p>`)).join('')}</details>`);}
