setInterval(async()=>{if(adminRoute||booting||!cloud.user)return;const clock=$('#current-clock');const lesson=$('#current-lesson');if(lesson){const config=scheduleFor(s.data.profile,s.classTables[sunday(today())]),now=currentLesson(config.rows,tableFor(s.data.profile,s.classTables[sunday(today())],sunday(today())),new Date(),config.examMode);lesson.textContent=now?'지금 · '+now.label+' · '+now.subject+' ('+now.start+'~'+now.end+')':'지금 · 등록된 수업·일과 시간이 아니에요';}if(clock)clock.textContent=new Date().toLocaleString('ko-KR');const m=today()+':'+new Date().getMinutes();if(m!==minute&&!document.querySelector('dialog[open]')&&!document.querySelector('form:focus-within')&&['home','planner'].includes(view)){minute=m;capture();render();}},1000);
setInterval(async()=>{if(booting||!cloud.user)return;try{if(typeof Notification==='undefined'||Notification.permission!=='granted'||localStorage.getItem('meta-reminders-'+cloud.user.id)!=='enabled')return;const p=s.data.profile.reminderSettings||defaultReminders(),key='meta-reminders-'+cloud.user.id+'-sent',sent=JSON.parse(localStorage.getItem(key)||'{}'),now=Date.now();if(s.data.tasks.some(t=>!t.done))for(const time of scheduledReminderSlots(p)){const tag='daily:'+today()+':'+time;if(!sent[tag]){await showReminder('설정한 시각이에요. 오늘의 할일을 확인하세요.');sent[tag]=now;}}if(p.deadline)for(const t of s.data.tasks.filter(t=>!t.done&&t.fields.due)){const due=deadlineStamp(t),tag=t.id+':'+due;if(due>=now&&due-now<=1800000&&!sent[tag]){await showReminder('곧 마감인 할일이 있어요.');sent[tag]=now;}}for(const[k,v]of Object.entries(sent))if(now-v>172800000)delete sent[k];localStorage.setItem(key,JSON.stringify(sent));}catch{}},15000);
