async function pollMessages(){if(adminRoute||polling||booting||!cloud.user||document.hidden)return;polling=true;try{const id=cloud.user.id,previous=new Map((s.community.rooms||[]).map(r=>[r.id,r.latest]));await refreshCommunity();if(cloud.user?.id!==id)return;updateUnread();for(const r of s.community.rooms||[])if(r.unread&&r.latest&&previous.get(r.id)!==r.latest&&!(view==='social'&&s.room?.id===r.id))toast('새 메시지가 있어요. 소통에서 확인하세요.');if(view==='social'&&s.room){const roomId=s.room.id,result=await api('/api/campus?room='+roomId);if(cloud.user?.id!==id)return;if(s.room?.id===roomId){s.messages=result.messages;if($('#messages'))$('#messages').innerHTML=messagesHtml(s);if(result.messages.length){await campus('read-room',{roomId,through:result.messages.at(-1).created_at});const r=s.community.rooms.find(r=>r.id===roomId);if(r)r.unread=0;updateUnread();}}}if(view==='social'&&!document.querySelector('dialog[open],form:focus-within')){capture();render();}}catch(err){if([401,403].includes(err.status)){s.room=null;s.messages=[];delete s.forms['message-form'];if(view==='social')render();}error(err);}finally{polling=false;}}
setInterval(pollMessages,10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollMessages();});window.addEventListener('online',pollMessages);
